import base64, hashlib, hmac, json

def b64e(b):
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode()

def b64d(s):
    return base64.urlsafe_b64decode(s + "=" * (-len(s) % 4))

def imzala(yuk, anahtar):
    baslik = {"alg": "HS256", "typ": "JWT"}
    govde = b64e(json.dumps(baslik, separators=(",", ":")).encode()) + "." + \
            b64e(json.dumps(yuk, separators=(",", ":")).encode())
    imza = hmac.new(anahtar, govde.encode(), hashlib.sha256).digest()
    return govde + "." + b64e(imza)

def dogrula(token, anahtar, simdi, aud, iss):
    b, y, i = token.split(".")
    if json.loads(b64d(b)).get("alg") != "HS256":       # alg=none saldırısına kapı açma
        return "algoritma reddedildi"
    beklenen = hmac.new(anahtar, f"{b}.{y}".encode(), hashlib.sha256).digest()
    if not hmac.compare_digest(beklenen, b64d(i)):
        return "imza geçersiz"
    yuk = json.loads(b64d(y))
    if simdi >= yuk["exp"]:
        return "süresi dolmuş"
    if yuk.get("iss") != iss or aud not in (yuk["aud"] if isinstance(yuk["aud"], list) else [yuk["aud"]]):
        return "yanlış yayıncı ya da hedef"
    return yuk

ANAHTAR = b"pusula-ik-ornek-anahtar-32-bayt!"
t = imzala({"sub": "418", "iss": "pusula-sso", "aud": "izin-api", "exp": 1_000_900}, ANAHTAR)
print(t[:40] + "...")
print(dogrula(t, ANAHTAR, 1_000_000, "izin-api", "pusula-sso"))
print(dogrula(t, ANAHTAR, 1_000_000, "bordro-api", "pusula-sso"))
print(dogrula(t, ANAHTAR, 1_001_000, "izin-api", "pusula-sso"))
sahte = t.rsplit(".", 1)[0][:-2] + "fQ." + t.rsplit(".", 1)[1]
print(dogrula(sahte, ANAHTAR, 1_000_000, "izin-api", "pusula-sso"))
''') + '\n<div class="warn"><b>Bilinen JWT saldırıları</b><b>alg=none</b>: başlıkta algoritmayı "none" yapıp imzayı silmek; tokendaki <code>alg</code> alanına güvenen kütüphane kandırılır. <b>Algoritma karışıklığı</b>: RS256 bekleyen sunucuya, açık anahtarı HMAC anahtarı gibi kullanılan HS256 token yollamak. Çözüm aynı: kabul edilen algoritmaları sunucuda sabitle (<code>jwt.decode(t, key, algorithms=["HS256"])</code>), tokendaki <code>alg</code>\'a göre davranma.</div>\n<h3>Anahtar döndürme ve kid</h3>\n<p>İmza anahtarı bir gün değişecek (sızma, periyodik döndürme). Başlıktaki <code>kid</code> hangi anahtarla imzalandığını söyler; sunucu birkaç anahtarı aynı anda tanır: yeni tokenlar yeni anahtarla imzalanır, eski anahtar yalnız doğrulama için en uzun token ömrü kadar tutulur, sonra silinir. Asimetrik algoritmalarda (RS256, ES256) açık anahtarlar bir JWKS uç noktasında yayınlanır.</p>\n\n<h2>Access ve refresh token</h2>\n<p>JWT\'yi iptal etmek zor olduğu için access token kısa ömürlü olur (5–15 dakika). Kullanıcıyı her 15 dakikada bir giriş ekranına göndermemek için yanında uzun ömürlü bir <b>refresh token</b> verilir; bu token yalnız yetki sunucusuna gider ve yeni bir access token alır. Refresh token sunucuda (özeti) saklanan, iptal edilebilen bir kayıttır.</p>\n<ul>\n<li><b>Döndürme (rotation):</b> her yenilemede eski refresh token geçersiz olur, yenisi verilir.</li>\n<li><b>Yeniden kullanım tespiti (reuse detection):</b> geçersiz olmuş bir refresh token tekrar gelirse token çalınmış demektir; o "aileye" ait tüm tokenlar iptal edilir, kullanıcı yeniden giriş yapar.</li>\n<li><b>İptal listesi (denylist):</b> çıkışta ya da hesap kapatılınca access tokenın <code>jti</code>\'si süresi dolana kadar listede tutulur.</li>\n</ul>\n' + py(r'''
import itertools

sayac = itertools.count(1)
gecerli, kullanilmis, aile_of = {}, set(), {}

def ver(kullanici, aile):
    t = f"rt-{next(sayac)}"
    gecerli[t] = kullanici
    aile_of[t] = aile
    return t

def yenile(t):
    if t in kullanilmis:                        # çalıntı token tekrar geldi
        aile = aile_of[t]
        for x in [x for x in gecerli if aile_of[x] == aile]:
            del gecerli[x]
        return "ALARM: aile iptal edildi"
    kullanici = gecerli.pop(t)
    kullanilmis.add(t)
    return ver(kullanici, aile_of[t])

r1 = ver("emp-418", aile="cihaz-A")
r2 = yenile(r1)
print(r1, "->", r2)
print(yenile(r1))           # saldırgan eski tokenı denedi
print("geçerli tokenlar:", gecerli)
''') + '\n\n<h2>Yetkilendirme modelleri: RBAC ve ABAC</h2>\n<p><b>RBAC</b> (Role-Based Access Control) kullanıcıya rol, role izin verir: <code>calisan → izin:oku_kendi, izin:iste</code>; <code>yonetici → calisan\'ın her şeyi + izin:onayla</code>. Basit ve denetlenebilirdir. Ama "yönetici yalnız <b>kendi ekibinin</b> iznini onaylar" kuralını rol tek başına ifade edemez. Burada <b>ABAC</b> (Attribute-Based Access Control) devreye girer: karar, kullanıcının, kaynağın ve ortamın özniteliklerine bakan kurallarla verilir (<code>kaynak.calisan.manager_id == kullanici.emp_id</code>, mesai saati, şehir...). Pratikte ikisi birlikte kullanılır: rol kaba kapıyı açar, öznitelik kuralı satırı süzer.</p>\n' + py(r'''
import veri

calisanlar = {c["emp_id"]: c for c in veri.kayitlar("pusula_ik", "ik_employees")}
izinler = veri.kayitlar("pusula_ik", "ik_leaves")

ROL_IZIN = {"calisan": {"izin:oku"}, "yonetici": {"izin:oku", "izin:onayla"}, "ik": {"izin:oku", "izin:onayla"}}

def gorebilir_mi(kullanici, izin_kaydi):
    if "izin:oku" not in ROL_IZIN[kullanici["rol"]]:          # RBAC kapısı
        return False
    if kullanici["rol"] == "ik":
        return True
    sahip = calisanlar[izin_kaydi["emp_id"]]
    return sahip["emp_id"] == kullanici["emp_id"] or sahip["manager_id"] == kullanici["emp_id"]   # ABAC

riza = {"emp_id": 13, "rol": "yonetici"}
cem = {"emp_id": 418, "rol": "calisan"}
